//! The clothoid against an independent computation: arbitrary precision Fresnel integrals
//! (mpmath, 50 digits), generated by `tests/data/gen_clothoid.py`. Each row is
//! (length, radius, x, y) of the end of a clothoid from a tangent to a circle of that radius,
//! in the frame of its start.
//!
//! Achieved agreement (printed by `cargo test -- --nocapture`): the quadrature that evaluates
//! every alignment, and the power series of `clothoid_xy`, both agree with the reference to
//! better than 1e-12 m on these cases (lengths 30 to 250 m, spiral angles up to 0.5 rad). The
//! assertion allows 1e-10 m.

use afrobim_alignment::{clothoid_xy, AlignmentElement, Turn};

const REFERENCE: [(f64, f64, f64, f64); 8] = [
    (100.0, 300.0, 99.72257921782744, 5.544542365628803),
    (60.0, 150.0, 59.760444034412046, 3.988585963871698),
    (150.0, 500.0, 149.66285138001402, 7.487955054443561),
    (200.0, 800.0, 199.687725974641, 8.324037360709454),
    (30.0, 50.0, 29.7311226663308, 2.9807694262868845),
    (120.0, 120.0, 117.03452258404134, 19.64568568508407),
    (80.0, 1000.0, 79.98720094811314, 1.0665447681106492),
    (250.0, 400.0, 247.56960680525467, 25.860577892448177),
];

#[test]
fn quadrature_and_series_agree_with_mpmath_fresnel() {
    let (mut worst_quad, mut worst_series) = (0.0f64, 0.0f64);
    for (l, r, x, y) in REFERENCE {
        let e = AlignmentElement::spiral(0.0, 0.0, 0.0, l, None, Some(r), Turn::Left);
        let (qx, qy, _) = e.end();
        let (sx, sy) = clothoid_xy(l, r);
        worst_quad = worst_quad.max((qx - x).abs()).max((qy - y).abs());
        worst_series = worst_series.max((sx - x).abs()).max((sy - y).abs());
    }
    eprintln!("clothoid agreement with mpmath: quadrature {worst_quad:.3e} m, series {worst_series:.3e} m");
    assert!(worst_quad < 1e-10, "quadrature {worst_quad}");
    assert!(worst_series < 1e-10, "series {worst_series}");
}

#[test]
fn design_curve_data_uses_the_same_clothoid() {
    use afrobim_design::{HorizontalDesign, Pi};
    let d = HorizontalDesign::new("C", 0.0, vec![Pi::point(0.0, 0.0), Pi::spiral_curve(1000.0, 0.0, 300.0, 100.0, 100.0), Pi::point(1500.0, 866.0254037844386)]);
    let c = d.solve().unwrap().curve_at_pi(1).cloned().unwrap();
    assert!((c.spiral_in_xy.0 - 99.72257921782745).abs() < 1e-10);
    assert!((c.spiral_in_xy.1 - 5.544542365628803).abs() < 1e-10);
}
